#pragma once

// MergeShip2 -- the unified randomizer: one seed over Hyrule and Termina, generated by SoH's generator.
// Shipwright/mergeship2/docs/UNIFIED_RANDO_DESIGN.md. Off unless RSK_MERGESHIP_TERMINA is on; with it off every seed
// is exactly what it was (no location, item, region, setting or hash input of Termina takes part).
//
// Milestones here: M0 (the canonical item table, include/mergeship/MsItems.def, MergeShipMsItems.h), M1 (Majora's
// Mask's checks as world-tagged locations behind the Lost Woods door), M2 generator side (the MERGESHIP_SEED sections
// written by SpoilerLog_Write), M4 pools (every check 2Ship can shuffle, vanilla placements the logic needs, own-dungeon
// and song-location placement). Termina's logic itself (M4) is MergeShipTerminaLogic.h.
//
// The static data (RC_MM_*, RG_MM_*, RR_MM_*, RSK_MM_*, MergeShipTerminaData.cpp) is generated by
// tools/port_mm_rando.py from 2ship2harkinian's randomizer.

#include <cstddef>
#include <functional>
#include <vector>
#include <nlohmann/json.hpp>
#include "soh/Enhancements/randomizer/randomizerTypes.h"

// 2Ship's RandoCheckType, in its order (generated names: gMsTerminaCheckTypeNames).
typedef enum MsMMCheckType {
    MS_MMCT_UNKNOWN,
    MS_MMCT_BARREL,
    MS_MMCT_BUTTERFLY,
    MS_MMCT_CHEST,
    MS_MMCT_COW,
    MS_MMCT_CRATE,
    MS_MMCT_ENEMY_DROP,
    MS_MMCT_FREESTANDING,
    MS_MMCT_FROG,
    MS_MMCT_GRASS,
    MS_MMCT_HEART,
    MS_MMCT_BEEHIVE,
    MS_MMCT_MINIGAME,
    MS_MMCT_NPC,
    MS_MMCT_OWL,
    MS_MMCT_POT,
    MS_MMCT_REMAINS,
    MS_MMCT_SHOP,
    MS_MMCT_SKULL_TOKEN,
    MS_MMCT_SNOWBALL,
    MS_MMCT_SONG,
    MS_MMCT_STRAY_FAIRY,
    MS_MMCT_TINGLE_SHOP,
    MS_MMCT_TREE,
    MS_MMCT_WONDER_ITEM,
    MS_MMCT_MAX,
} MsMMCheckType;

// One Termina location and what 2Ship knows about it.
struct MsTerminaCheck {
    RandomizerCheck rc;
    const char* mmCheck;       // 2Ship RandoCheckId name, the key in the "mm" section's "checks"
    MsMMCheckType type;        // 2Ship RandoCheckType
    const char* mmScene;       // 2Ship SceneId name
    const char* mmVanillaItem; // 2Ship RandoItemId name
    RandomizerGet vanillaItem; // the same item in SoH (MsItems.def)
    RandomizerRegion region;   // the 2Ship region that first lists it, as RR_MM_* (M4's world graph)
};

// A 2Ship option. rsk is RSK_MAX for options passed through unchanged (value = defaultValue).
struct MsTerminaOption {
    RandomizerSettingKey rsk;
    const char* mmOption; // 2Ship RandoOptionId name, the key in the "mm" section's "options"
    const char* name;     // setting name (spoiler log "settings" key, menus)
    int minValue;         // 2Ship value of option index 0 (numeric options start at 1 for some)
    int defaultValue;     // 2Ship default
};

struct MsTerminaRegion {
    RandomizerRegion rr;
    const char* mmRegion; // 2Ship RandoRegionId name (RR_MAX = the pseudo-root, RR_MM_ROOT)
    const char* mmScene;
    int checkCount;
};

extern const char* const gMsTerminaCheckTypeNames[MS_MMCT_MAX];
extern const MsTerminaCheck gMsTerminaChecks[];
extern const size_t gMsTerminaCheckCount;
extern const MsTerminaOption gMsTerminaOptions[];
extern const size_t gMsTerminaOptionCount;
extern const MsTerminaRegion gMsTerminaRegions[];
extern const size_t gMsTerminaRegionCount;

// The unified mode is on for the seed being generated / loaded.
bool MergeShip_Termina_Enabled();
// A Termina location (RC_MM_*).
bool MergeShip_Termina_IsTerminaCheck(RandomizerCheck rc);
const MsTerminaCheck* MergeShip_Termina_GetCheck(RandomizerCheck rc);
// A Termina setting (RSK_MM_*); its spoiler/menu name for option.cpp.
bool MergeShip_Termina_IsTerminaSetting(RandomizerSettingKey rsk);
const std::string* MergeShip_Termina_SettingText(RandomizerSettingKey rsk, bool description);
// Whether a setting takes part in the seed hash (playthrough.cpp) and the spoiler's "settings": the Termina ones
// only while the unified mode is on.
bool MergeShip_Termina_SettingCounts(RandomizerSettingKey rsk);

// Seed generation (SeedContext::GenerateLocationPool, item_pool.cpp GenerateItemPool). PrepareLocationPool decides
// which Termina checks are shuffled (2Ship's GeneratePools rules, from the RSK_MM_* settings) and must run first;
// the location pool then takes the ones IsInLocationPool says. AddItemsToPool adds their vanilla items (and 2Ship's
// extra pool items), as SoH items, applying the unified pool caps (UNIFIED_RANDO_DESIGN.md): `others` are the
// item_pool.cpp pools that already hold items, counted for the caps.
void MergeShip_Termina_PrepareLocationPool();
bool MergeShip_Termina_IsInLocationPool(RandomizerCheck rc);
// Run time (trackers, M7): whether 2Ship's randomizer handles this check in the loaded unified seed, so finding it
// writes the ledger. From the seed's Termina options alone (the RNG of partly shuffled Spider Houses is not kept: all
// of a shuffled house's tokens count).
bool MergeShip_Termina_IsTrackedCheck(RandomizerCheck rc);
void MergeShip_Termina_AddItemsToPool(std::vector<RandomizerGet>& itemPool,
                                      const std::vector<const std::vector<RandomizerGet>*>& others);
// fill.cpp Fill, after Hyrule's restricted pools: 2Ship's own restricted placements, through `assumedFill` (fill.cpp's
// AssumedFill): each temple's items confined to it (RSK_MM_PLACEMENT_* / RSK_MM_SHUFFLE_BOSS_REMAINS "Own Dungeon"),
// and MM's songs on MM's song checks (RSK_MM_SHUFFLE_SONGS "Song Locations"; spare song checks get junk, as 2Ship).
void MergeShip_Termina_PlaceRestrictedItems(
    const std::function<void(const std::vector<RandomizerGet>&, const std::vector<RandomizerCheck>&)>& assumedFill);

// For Termina's logic (MergeShipTerminaLogic.h): a 2Ship option's value by gMsTerminaOptions index (= MMOption), a
// shop or Tingle check's price (0 when it has none), and the items the logic starts with (2Ship's computed starting
// items the pool left out, the clock of clock shuffle).
int MergeShip_Termina_OptionValue(size_t optionIndex);
uint16_t MergeShip_Termina_GetPrice(RandomizerCheck rc);
const std::vector<RandomizerGet>& MergeShip_Termina_LogicStartingItems();
// A new file of the loaded unified seed (savefile.cpp SetStartingItems): when Termina's stray fairies are "Start With",
// MM's stray fairy counts Hyrule starts with, by MMStrayFairyArea (Clock Town's 1, then 15 per temple), and true. The
// counts are in the shared save both engines set on every trip (MsSharedSave.strayFairies), so Hyrule's must start
// full as 2Ship's do (its GetComputedStartingItems), or the first arrival in Termina would set them back to 0. False
// (nothing to give) otherwise. Termina's maps, compasses and keys are 2Ship's save alone: 2Ship gives them.
bool MergeShip_Termina_StartingStrayFairies(uint8_t counts[5]);

// Spoiler log (3drando/spoiler_log.cpp): with the unified mode on, the SoH spoiler becomes the "oot" section of a
// MERGESHIP_SEED (include/mergeship/MsItems.h) and this adds "shared", "mm", "hints" and "playthrough".
nlohmann::ordered_json MergeShip_Termina_WrapSeed(nlohmann::ordered_json ootSpoiler);
// SeedContext::ParseSpoiler: the SoH spoiler inside a MERGESHIP_SEED (the file itself otherwise).
const nlohmann::json& MergeShip_Termina_UnwrapSeed(const nlohmann::json& file);

// For the test harness: a short summary of the last generated seed (counts per world, cross-world placements), with
// the M4 lines of MergeShip_Termina_LogicSummary (pool per world and check type, playthrough spheres in Termina, what a
// search with every placed item reaches: Majora, the bosses, Termina's locations and regions).
std::vector<std::string> MergeShip_Termina_Summary();
std::vector<std::string> MergeShip_Termina_LogicSummary();
